import type { AxisKey, ReferenceEntry } from './references';

type ProfileInput = Pick<ReferenceEntry, 'id' | 'name' | 'period' | 'rationale' | 'caveats' | 'sources'> & {
  scores?: Partial<Record<AxisKey, number>>;
  reasons?: Partial<Record<AxisKey, string>>;
  confidence?: 'high' | 'medium';
};

const axes: AxisKey[] = ['est', 'rep', 'pod', 'imi', 'dip', 'int', 'eco', 'con', 'com', 'rel', 'mor', 'tec'];

/** Unknown axes stay at 50 and are not scored as evidence of moderation. */
const profile = (input: ProfileInput): ReferenceEntry => {
  const { scores: rawScores, reasons: rawReasons, confidence, ...entry } = input;
  const scores = rawScores ?? {};
  const reasons = rawReasons ?? {};
  const unsupported = Object.keys(scores).filter((axis) => !reasons[axis as AxisKey]);
  if (unsupported.length) throw new Error(`${input.id}: non-center axes need axis-specific source reasoning: ${unsupported.join(', ')}`);

  const vec = Object.fromEntries(axes.map((axis) => [axis, scores[axis] ?? 50])) as Record<AxisKey, number>;
  const evidence = Object.fromEntries(Object.keys(scores).map((axis) => [axis, confidence ?? 'medium'])) as ReferenceEntry['evidence'];
  const axisEvidence = Object.fromEntries(Object.entries(reasons).map(([axis, rationale]) => [axis, {
    sourceTitles: entry.sources[0]?.title ? [entry.sources[0].title] : [],
    rationale,
  }])) as ReferenceEntry['axisEvidence'];

  return {
    ...entry,
    id: `ideology-left-${entry.id}`,
    kind: 'ideology',
    category: 'ideology',
    vec,
    evidence,
    axisEvidence,
  };
};

const src = (title: string, url: string, note: string) => ({ title, url, note });

